EOF
echo -e "${NC}"
echo -e "  ${BOLD}主题：${CYAN}hugo-theme-stack${NC}"
echo -e "  ${BOLD}服务：${CYAN}Hugo + Nginx + Decap CMS${NC}\n"
[[ $EUID -ne 0 ]] && error "请用 root 权限运行：sudo bash $0"
